UPDATE
	sianadb.market.category






				SET
					ca_seq = ca_seq + 1
				WHERE 1 = 1
				AND ca_seq  <=  #{maxSeq}
				AND ca_seq  >  #{minSeq}



				SET
					ca_seq = ca_seq - 1
				WHERE 1 = 1
				AND ca_seq  <=  #{maxSeq}
				AND ca_seq  >  #{minSeq}



				SET
					ca_seq = ca_seq + 1
				WHERE 1 = 1
				AND ca_seq  >=  #{caSeq}


